export const canonical39RetiredGeneratorSource = "import assert from \"node:assert/strict\";\nimport { createHash } from \"node:crypto\";\nimport { existsSync, lstatSync, readFileSync, readdirSync, writeFileSync } from \"node:fs\";\nimport { mkdir } from \"node:fs/promises\";\nimport { join, relative } from \"node:path\";\nimport { gzipSync } from \"node:zlib\";\nimport { Database } from \"bun:sqlite\";\n\nconst sourceCommit = \"5f2735191640037c86d9949bc1d7f04b2ef09ffe\";\nconst sourceTree = \"12b4cec2c26b328e41d763ecca41c9a844d3dec3\";\nconst sourceManifestSha256 = \"586baa77f131e0157588803d91ee62d8918cf57b5991208858b0ef5f88b5e144\";\nconst sourceHashes = {\n  \"src/storage/state-store.ts\": \"bde901608092489d89aa9acdfde320a0cf2959a6bd3659879cf7ac9dfab43e89\",\n  \"src/domain/runtime-profile.ts\": \"49305314d5619f828b685a8e45d5bd055719c7661e77db8ea9e44924de4f85b2\",\n  \"package.json\": \"ef8779bd5fa796f395ad3d064710e247a89eb0cbd4023dc069b4daaad8e12d3c\",\n  \"bun.lock\": \"5a2b90063d8eb1aa55e18be71abbca59c1f051a9358a2a36ff89698d066b182a\",\n};\nconst hash = (value: string | Uint8Array) => createHash(\"sha256\").update(value).digest(\"hex\");\nconst root = import.meta.dir;\nconst output = join(root, \"retired-effects2\");\nassert.equal(Bun.version, \"1.3.14\");\nassert.equal(lstatSync(root).mode & 0o777, 0o700);\nassert.equal(existsSync(output), false, \"Never overwrite or restamp a capture.\");\nfor (const [path, expected] of Object.entries(sourceHashes)) assert.equal(hash(readFileSync(join(root, path))), expected);\nconst sourceFiles: { path: string; sha256: string }[] = [];\nfunction visit(directory: string) {\n  for (const entry of readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {\n    const path = join(directory, entry.name);\n    if (entry.isDirectory()) visit(path);\n    else if (entry.isFile()) sourceFiles.push({ path: relative(root, path), sha256: hash(readFileSync(path)) });\n    else throw new Error(\"Unexpected archived source entry.\");\n  }\n}\nvisit(join(root, \"src\"));\nassert.equal(sourceFiles.length, 282);\nassert.equal(hash(JSON.stringify(sourceFiles)), sourceManifestSha256);\nconst dependencies = { \"@agentclientprotocol/sdk\": \"1.4.0\", \"@hraness/oh\": \"0.2.7\",\n  \"@openai/codex\": \"0.153.2\", convex: \"1.45.0\", zod: \"4.4.3\" };\nfor (const [name, expected] of Object.entries(dependencies)) {\n  assert.equal(JSON.parse(readFileSync(join(root, \"node_modules\", name, \"package.json\"), \"utf8\")).version, expected);\n}\nconst { StateStore } = await import(\"./src/storage/state-store\");\nconst { initializeStatePaths, resolveStatePaths } = await import(\"./src/storage/paths\");\nconst { effectiveDevinRuntimeProfileSchema, effectiveRuntimeProfileSchema } = await import(\"./src/domain/runtime-profile\");\nawait mkdir(output, { mode: 0o700 });\nconst fixedTime = 39_002;\nconst options = { now: () => fixedTime };\nconst snapshot = (databasePath: string) => {\n  const database = new Database(databasePath, { readonly: true, strict: true });\n  try {\n    const schema = database.query(\"SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name\").all();\n    const tables = database.query(\"SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name\").all() as { name: string }[];\n    assert.ok(tables.length <= 256);\n    const rows: Record<string, unknown[]> = {};\n    for (const { name } of tables) {\n      assert.match(name, /^[a-zA-Z0-9_]+$/);\n      rows[name] = database.query(`SELECT * FROM \"${name}\"`).all().sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));\n      assert.ok(rows[name].length <= 4096);\n    }\n    const result = { userVersion: database.query(\"PRAGMA user_version\").get(), schema, rows,\n      foreignKeyCheck: database.query(\"PRAGMA foreign_key_check\").all(),\n      inspectionChanges: database.query(\"SELECT total_changes() AS count\").get() };\n    assert.deepEqual(result.foreignKeyCheck, []);\n    assert.deepEqual(result.inspectionChanges, { count: 0 });\n    assert.ok(Buffer.byteLength(JSON.stringify(result)) < 8 * 1024 * 1024);\n    return result;\n  } finally { database.close(false); }\n};\nconst generatorSource = readFileSync(import.meta.path, \"utf8\");\nconst summaries = [];\nfor (const kind of [\"source_switch\", \"target_switch\", \"queue_dispatch\", \"mixed_history\"] as const) {\n  const directory = join(output, kind);\n  await mkdir(directory, { mode: 0o700 });\n  const paths = resolveStatePaths({ rootDirectory: join(directory, \"state\") });\n  await initializeStatePaths(paths);\n  const store = new StateStore(paths, options);\n  const initial = snapshot(paths.database);\n  assert.deepEqual(initial.userVersion, { user_version: 39 });\n  const createdProfile = store.createProfile(`Canonical39 synthetic ${kind}`);\n  const advanced = store.nextProfileGeneration(createdProfile.id);\n  assert.equal(store.setProfileState(advanced.id, advanced.processGeneration, \"signed_in\", {\n    email: \"canonical39-retired@example.com\", plan: \"Plus\",\n  }), true);\n  const profile = store.requireProfile(advanced.id);\n  assert.equal(store.allocateNextUsageRevision(profile.id), 1);\n  const provider = kind === \"target_switch\" ? \"codex\" : \"devin\";\n  const created = store.createSession({ profileId: profile.id, provider,\n    preset: provider === \"codex\" ? \"high\" : \"astra\", fastEnabled: false });\n  const session = store.bindSession({ sessionId: created.id, expectedRevision: created.revision,\n    providerThreadId: `canonical39-synthetic-${kind}`, state: \"idle\" });\n  // These are synthetic inputs to the released trusted storage boundary.\n  // No provider login, process launch, native custody, or provider effect runs.\n  const devinProfile = effectiveDevinRuntimeProfileSchema.parse({\n    profileId: profile.id, processGeneration: profile.processGeneration, observedAt: fixedTime,\n    preset: \"astra\", model: \"gpt-6-astra\", reasoningEffort: \"provider-default\",\n    devinVersion: \"3000.6.14\", protocolVersion: 1, isolatedHome: true,\n  });\n  const codexProfile = effectiveRuntimeProfileSchema.parse({\n    profileId: profile.id, processGeneration: profile.processGeneration, observedAt: fixedTime,\n    preset: \"high\", model: \"gpt-6-astra\", reasoningEffort: \"max\", serviceTier: null, fast: false,\n    approvalPolicy: \"on-request\", reviewMode: \"auto_review\", permissionProfile: \":workspace\",\n    computerUse: true, pluginCapability: true, enabledApps: [],\n  });\n  const runtimeProfile = provider === \"devin\" ? devinProfile : codexProfile;\n  const runtime = store.recordSessionRuntimeProfile({ sessionId: session.id,\n    sourceKind: \"session_start\", sourceId: `canonical39-synthetic-runtime-${kind}`, profile: runtimeProfile });\n  let extra: Record<string, unknown>;\n  if (kind === \"source_switch\" || kind === \"target_switch\") {\n    const targetProvider = kind === \"target_switch\" ? \"devin\" : \"codex\";\n    const targetPreset = targetProvider === \"devin\" ? \"astra\" : \"high\";\n    const idempotencyKey = kind === \"source_switch\"\n      ? \"39000000-0000-4000-8000-000000000011\" : \"39000000-0000-4000-8000-000000000012\";\n    const prepared = store.prepareMutation({ idempotencyKey, kind: \"session.switch\", authorityId: session.id,\n      authorityGeneration: profile.processGeneration, request: { provider: targetProvider, preset: targetPreset,\n        presetContract: 2, targetProfileId: profile.id, seedDigest: \"c\".repeat(64) } });\n    const evidence = { kind: \"session.switch\" as const, daemonGeneration: 0, requestedAccountId: null,\n      requestedPreset: null, sourceProfileId: profile.id, sourceProcessGeneration: profile.processGeneration,\n      sourceProvider: provider, sourceProviderThreadId: session.providerThreadId!,\n      sourcePreset: provider === \"devin\" ? \"astra\" as const : \"high\" as const,\n      targetProfileId: profile.id, targetProcessGeneration: profile.processGeneration,\n      targetProvider, targetPreset, transcriptDigest: \"b\".repeat(64), seedDigest: \"c\".repeat(64),\n      seedIncludedRecords: 0, seedOmittedRecords: 0,\n      runtimeProfile: targetProvider === \"devin\" ? devinProfile : codexProfile };\n    store.beginSessionProviderSwitchEffect({ attemptId: prepared.id, sessionId: session.id,\n      ...(targetProvider === \"devin\" ? { providerAuthentication: {\n        profileId: profile.id, processGeneration: profile.processGeneration, provider: \"devin\" as const, signedIn: true as const,\n      } } : {}), evidence });\n    const mutation = store.readMutation(idempotencyKey);\n    assert.equal(mutation?.state, \"effect_started\");\n    extra = { idempotencyKey, mutation };\n  } else {\n    const queue = store.enqueue(session.id, \"legacy pending send\");\n    if (kind === \"queue_dispatch\") {\n      store.beginQueueEffect({ queueId: queue.id, sessionId: session.id, profileGeneration: profile.processGeneration,\n        evidence: { kind: \"queue.dispatch\", queueId: queue.id, sessionId: session.id,\n          providerThreadId: session.providerThreadId!, profileGeneration: profile.processGeneration,\n          baseline: { providerUpdatedAt: null, status: \"idle\", activeTurnId: null }, clientMessageId: queue.id,\n          messageDigest: hash(queue.message), runtimeProfile: devinProfile } });\n      assert.equal(store.requireQueue(queue.id).state, \"dispatching\");\n      extra = { queue: store.requireQueue(queue.id), queueEffect: store.readQueueEffect(queue.id) };\n    } else {\n      const codex = store.createSession({ profileId: profile.id, provider: \"codex\", preset: \"high\", fastEnabled: false });\n      const claude = store.createSession({ profileId: profile.id, provider: \"claude\", preset: \"fable-max\", fastEnabled: false });\n      const usage = store.appendSessionEvent({ sessionId: session.id, accountId: profile.id,\n        providerGeneration: profile.processGeneration, providerConnectionId: null,\n        body: { type: \"token_usage\", turnId: null, inputTokens: null, cachedInputTokens: null, outputTokens: null,\n          reasoningOutputTokens: null, totalTokens: 42, modelContextWindow: 200000,\n          providerCost: { amount: 0.5, currency: \"USD\" } } });\n      const idempotencyKey = \"39000000-0000-4000-8000-000000000014\";\n      store.prepareMutation({ kind: \"session.send\", authorityId: session.id, authorityGeneration: profile.processGeneration,\n        request: { message: \"rejected\" }, idempotencyKey });\n      extra = { queue, codex, claude, usage, idempotencyKey, mutation: store.readMutation(idempotencyKey) };\n    }\n  }\n  const finalSnapshot = snapshot(paths.database);\n  assert.deepEqual(finalSnapshot.rows.migrations, initial.rows.migrations);\n  const retained = { profile, session, runtimeProfile, runtime, ...extra };\n  store.close();\n  const reopened = new StateStore(paths, options);\n  assert.deepEqual(snapshot(paths.database), finalSnapshot);\n  assert.deepEqual(reopened.requireSession(session.id), session);\n  assert.deepEqual(reopened.latestSessionRuntimeProfile(session.id), runtime);\n  reopened.close();\n  const checkpoint = new Database(paths.database, { create: false, strict: true });\n  const checkpointResult = checkpoint.query(\"PRAGMA wal_checkpoint(TRUNCATE)\").get();\n  checkpoint.close(false);\n  assert.equal((checkpointResult as { busy: number }).busy, 0);\n  const beforeReadonly = hash(readFileSync(paths.database));\n  const readonly = new StateStore(paths, { readonly: true });\n  assert.deepEqual(snapshot(paths.database), finalSnapshot);\n  readonly.close();\n  const bytes = readFileSync(paths.database);\n  assert.equal(hash(bytes), beforeReadonly);\n  const metadata = { sourceCommit, sourceTree, schemaVersion: 39, sourceHashes, sourceManifestSha256,\n    generatorSha256: hash(generatorSource), bunVersion: Bun.version, dependencies, fixedTime, kind,\n    provenance: { syntheticControlPlaneOnly: true, archivedPublicApisOnly: true, nativeProviderEffects: 0,\n      noNativeCustodyProof: true, rawSqlRowOrSchemaWrites: false, randomizedIdentifiers: true,\n      writableReopenUnchanged: true, readonlyReopenUnchanged: true, readonlyDatabaseHashUnchanged: true,\n      noCurrentMergedAdmissionClaim: true },\n    databaseSha256: hash(bytes), databaseBytes: bytes.length, checkpointResult, retained, snapshot: finalSnapshot };\n  const text = JSON.stringify(metadata);\n  for (const forbidden of [root, \"/Users/\", \"/private/\", \"/tmp/\", \"/home/\", \"/Volumes/\"]) {\n    assert.equal(text.includes(forbidden), false);\n    assert.equal(bytes.includes(Buffer.from(forbidden)), false);\n  }\n  writeFileSync(join(directory, \"state.sqlite.gz\"), gzipSync(bytes), { mode: 0o600, flag: \"wx\" });\n  writeFileSync(join(directory, \"fixture.json\"), `${JSON.stringify(metadata, null, 2)}\\n`, { mode: 0o600, flag: \"wx\" });\n  summaries.push({ kind, databaseSha256: hash(bytes), databaseBytes: bytes.length,\n    sessions: finalSnapshot.rows.sessions.length, mutationEvidence: finalSnapshot.rows.mutation_effect_evidence.length,\n    queueEvidence: finalSnapshot.rows.queue_effect_evidence.length, archivedReopensUnchanged: true });\n}\nfor (const [path, expected] of Object.entries(sourceHashes)) assert.equal(hash(readFileSync(join(root, path))), expected);\nwriteFileSync(join(output, \"source-manifest.json\"), `${JSON.stringify(sourceFiles, null, 2)}\\n`, { mode: 0o600, flag: \"wx\" });\nconsole.log(JSON.stringify({ sourceCommit, generatorSha256: hash(generatorSource), summaries }));\n";
