export const canonical39RetiredDatabaseBytes = (kind: Canonical39RetiredKind): Uint8Array => {
  const fixture = canonical39RetiredFixtures[kind];
  if (createHash("sha256").update(canonical39RetiredGeneratorSource).digest("hex") !== fixture.generatorSha256) {
    throw new Error("CANONICAL39_RETIRED_GENERATOR_MISMATCH");
  }
  const kinds = ["source_switch", "target_switch", "queue_dispatch", "mixed_history"] as const;
  const maximum = kinds.reduce((sum, key) => sum + canonical39RetiredFixtures[key].databaseBytes, 0);
  const all = gunzipSync(Buffer.from(gzipBase64, "base64"), { maxOutputLength: maximum });
  if (all.length !== maximum) throw new Error("CANONICAL39_RETIRED_CAPTURE_MISMATCH");
  let offset = 0;
  for (const key of kinds) {
    const entry = canonical39RetiredFixtures[key];
    const bytes = all.subarray(offset, offset + entry.databaseBytes);
    if (createHash("sha256").update(bytes).digest("hex") !== entry.databaseSha256) {
      throw new Error("CANONICAL39_RETIRED_CAPTURE_MISMATCH");
    }
    offset += entry.databaseBytes;
  }
  const start = kinds.slice(0, kinds.indexOf(kind)).reduce((sum, key) => sum + canonical39RetiredFixtures[key].databaseBytes, 0);
  return new Uint8Array(all.subarray(start, start + fixture.databaseBytes));
};
